confirmation.text:
[[[
  const on = entity.state === 'locked';
  const who = variables.label || entity.attributes.friendly_name || 'this lock';
  return `${on ? 'Unlock' : 'Lock'} ${who}?`;
]]]

card.background:
[[[
  const s = entity.state;
  const p = variables.pal || {};
  const k = s === 'locked' ? 'locked'
          : (s === 'unlocked' || s === 'open') ? 'unlocked'
          : (s === 'locking' || s === 'unlocking' || s === 'opening') ? 'moving'
          : s === 'jammed' ? 'jammed' : 'unknown';
  return (p[k] || {}).bg || 'rgba(255,255,255,0.10)';
]]]

